CREATE TABLE IF NOT EXISTS etf_fees (
  ticker TEXT PRIMARY KEY, isin TEXT NOT NULL, name TEXT NOT NULL, issuer TEXT, fund_standard_code TEXT, legal_fund_name TEXT,
  mapping_status TEXT NOT NULL, fee_display_status TEXT NOT NULL, collection_state TEXT,
  total_fee_pct REAL, ter_pct REAL, other_cost_pct REAL, trading_cost_pct REAL, effective_burden_cost_pct REAL,
  effective_date TEXT, verified_at TEXT, verification_status TEXT NOT NULL, primary_source_type TEXT, primary_source_url TEXT,
  dart_receipt_no TEXT, secondary_source_url TEXT, source_note TEXT, updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_etf_fees_verification_status ON etf_fees(verification_status);
CREATE INDEX IF NOT EXISTS idx_etf_fees_issuer ON etf_fees(issuer);
CREATE INDEX IF NOT EXISTS idx_etf_fees_burden_cost ON etf_fees(effective_burden_cost_pct);
